"""Files generated by the agent in a Telegram turn, sent back to the chat.

Counterpart of ``whatsapp.media.send_outputs``: ``ChatService`` snapshots the
session output folders around a turn (``session_turn.snapshot_outputs``) and
hands the new deliverables here. Telegram accepts any document type, so the only
limits are the Bot API upload cap and the channel's ``max_outbound_files``; what
is left out is announced with a link to the conversation in the chat-ui.

Also builds the "Continua su AION" link used in the reply footer.
"""

from __future__ import annotations

import asyncio
import logging
import mimetypes
from html import escape
from typing import Any, List, Optional, Tuple

from src.channels.telegram.redact import redact
from src.session_workspace import session_root

logger = logging.getLogger("aion.telegram")

# Bot API limits for uploads made by bots (multipart): 50 MB for documents,
# 10 MB for photos (https://core.telegram.org/bots/api#sending-files).
MAX_DOCUMENT_BYTES = 50 * 1024 * 1024
MAX_PHOTO_BYTES = 10 * 1024 * 1024
# Only these go inline as photos: Telegram recompresses them, which is fine for
# charts; anything else (webp, svg, ...) is sent as a document to keep it intact.
_PHOTO_MIMES = frozenset({"image/jpeg", "image/png"})


def conversation_url(conversation_id: str) -> Optional[str]:
    """chat-ui URL of the conversation, or None when only a loopback URL is known.

    A ``localhost`` link is useless on the user's phone, so in local dev the
    footer link and the "more files" message simply omit it.
    """
    from src.api.public_urls import _is_loopback_host_url, chat_base_url

    base = chat_base_url().rstrip("/")
    if not base or _is_loopback_host_url(base):
        return None
    return f"{base}/c/{conversation_id}"


def continue_link_html(conversation_id: str) -> Optional[str]:
    """Footer line linking the conversation in the chat-ui (None without a public URL)."""
    url = conversation_url(conversation_id)
    if not url:
        return None
    return f'<a href="{escape(url, quote=True)}">💬 Continua su AION</a>'


async def send_outputs(
    bot: Any,
    *,
    chat_id: int,
    thread_id: Optional[int],
    session_id: str,
    files: List[str],
    max_files: int,
) -> Tuple[int, int]:
    """Upload generated files (session-relative paths) to the Telegram chat.

    At most ``max_files`` files are sent, oldest first. Returns
    ``(sent, left_out)``: ``left_out`` counts files over the limit, too large or
    rejected by Telegram, which the caller announces with a link to the chat-ui.
    Never raises: a failed upload must not turn a delivered answer into an error.
    """
    from aiogram.types import BufferedInputFile

    root = session_root(session_id)
    sent = 0
    left_out = 0
    for rel in files:
        if sent >= max_files:
            left_out += 1
            continue
        path = root / rel
        try:
            size = path.stat().st_size
        except OSError:
            continue
        if size > MAX_DOCUMENT_BYTES:
            left_out += 1
            continue
        mime = (mimetypes.guess_type(path.name)[0] or "").lower()
        try:
            data = await asyncio.to_thread(path.read_bytes)
            upload = BufferedInputFile(data, filename=path.name)
            if mime in _PHOTO_MIMES and size <= MAX_PHOTO_BYTES:
                await bot.send_photo(chat_id, upload, message_thread_id=thread_id)
            else:
                await bot.send_document(chat_id, upload, message_thread_id=thread_id)
            sent += 1
        except Exception as e:  # noqa: BLE001 — network / Bot API errors
            logger.warning("telegram: generated file not sent: %s", redact(e))
            left_out += 1
    return sent, left_out


def more_files_html(count: int, conversation_id: str) -> str:
    """Notice for generated files that were not sent to the chat."""
    url = conversation_url(conversation_id)
    where = f'<a href="{escape(url, quote=True)}">su AION</a>' if url else "su AION"
    return f"📁 Altri {count} file sono disponibili {where}."
